servB.fetchBans = async () => [...bansB, { id: { user: "01JBANE000000000000000000E" }, reason: "outro" }];
await bg.sincronizarServidor(servB, (sid) => ({ serverId: sid, config: {}, client: c, sendEmbed: async () => {} }));
