  const { client, criarContexto } = montar({ bans: BAN, fetchBansFalha: true });
  const r = await bg.propagarSeFoiBan("ORIGEM", "01M3GCETEYEBC1KT3DPTK8PAT9", { client, criarContexto, espera: 0 });
