// ── 2. A espera do 429 acontece de verdade ────────────────────────────────
console.log("\n── rate limit: a espera do 429 roda? ──");
process.env.RR_PAUSA_MS = "1";
const db = await import("./modulos/core/db.js");
db.abrirBanco(process.env.DB_PATH);
