const novoCanal = (sid, nome, id = ulid(sid + "#" + nome)) => ({ id, serverId: sid, name: nome, type: "TextChannel", nsfw: false, sendMessage: async (p) => fazMsg(p, sid), fetchMessages: async () => [], deleteMessages: async () => {} });
