const textoDe = (p) => { const e = p?.embeds?.[0] ?? p; return `${e?.title ?? ""}\n${e?.description ?? ""}\n${(e?.fields ?? []).map((f) => `${f.name}\n${f.value}`).join("\n")}${typeof p?.content === "string" ? "\n" + p.content : ""}`; };
