  assert.match(editado[0], /Resposta: \*\*150 ms\*\*/);
  assert.match(editado[0], /relógio da máquina do bot está \*\*65 s adiantado\*\*/);
  editado.length = 0;
  await geral.cmdPing({ channel: canalPing, authorId: U2, createdAt: new Date(nasceu) }, [], ctxPing(false));
