const esSid = await servidorNovo("es");
const paginaEs = {};
// (comando de voz: o servidor do teste não está no TTS_SERVIDORES — a página dele é conferida pelo montador)
const restritosEs = [];
for (const id of ajudaReg.COMANDOS_COM_AJUDA) {
  if (HELP_ABRE_OUTRA.includes(id)) continue;
  // (2 nov 2026, P4) antes: o dono lia toda página no servidor em espanhol. agora: a que tem parte só dele, na DM
  // (o idioma da DM é o do servidor dele, o RELATORIO_SERVIDOR = esSid)
  let txt;
  if (temParteDoDono(id, "es")) {
    const antes = process.env.RELATORIO_SERVIDOR;
    process.env.RELATORIO_SERVIDOR = esSid;
    try { txt = (await say(`&ayuda ${nomeEs(id)}`, esSid, { dm: true })).texto; }
    finally { if (antes === undefined) delete process.env.RELATORIO_SERVIDOR; else process.env.RELATORIO_SERVIDOR = antes; }
  } else txt = (await say(`&ayuda ${nomeEs(id)}`, esSid)).texto;
  const c = REG.find((x) => x.id === id);
  if (c?.voz && /^🚫/.test(txt)) { restritosEs.push(id); continue; }
  paginaEs[id] = txt;
}
await t(`servidor em espanhol: as ${ajudaReg.COMANDOS_COM_AJUDA.length} páginas do registro saem em espanhol, com os nomes em espanhol`, async () => {
  const ruins = [];
  for (const [id, txt] of Object.entries(paginaEs)) {
    const ponha = (m) => ruins.push(`${id}: ${m}`);
    if (!txt.startsWith(`📖 Ayuda — &${nomeEs(id)}\n`)) ponha(`título: ${txt.split("\n")[0]}`);
    if (!/\*\*Uso:\*\* `/.test(txt)) ponha("sem **Uso:**");
    if (/\*\*(Usage|Permission|Example|Parameters of)\b|\*\*Subtopics\*\*/.test(txt)) ponha("rótulo em inglês");
    if (txt.includes("⁣") || txt.includes("[object Object]")) ponha("marca ou objeto na tela");
    // todo `&nome` citado é o nome em espanhol do comando (não o interno nem o inglês)
    for (const m of txt.matchAll(/&([a-zçãéíóúñ]+)/gi)) {
      const id2 = aliasesMod.idDoNome(m[1]);
      if (COMANDO_ES[id2] && m[1].toLowerCase() !== COMANDO_ES[id2]) ponha(`&${m[1]} (devia ser &${COMANDO_ES[id2]})`);
    }
    // o texto em espanhol chega inteiro: a tradução da tela não passa por cima
    // (o `aqui` do &log virava `here`, o `{usuario}` do &adeus virava `{user}`)
    // (o `<x>` vira `‹x›` na saída de toda mensagem: marcadores.js)
    const d = ajudaReg.detalhesDoRegistro("&", "es")[id];
    for (const l of [d.uso, ...String(d.desc).split("\n")].filter((x) => x && x.trim()))
      if (!txt.includes(protegerMarcadores(l))) ponha(`linha alterada: ${l.slice(0, 70)}`);
  }
  for (const id of ajudaReg.COMANDOS_COM_AJUDA.filter((x) => restritosEs.includes(x) || HELP_ABRE_OUTRA.includes(x))) {
    const det = geral.construirDetalhes("&", "en", "es")[id], d = ajudaReg.detalhesDoRegistro("&", "es")[id];
    if (det?.desc !== d.desc) ruins.push(`${id}: o montador não usa o espanhol do registro`);
  }
  assert.deepEqual(ruins, []);
  // e é mesmo espanhol (não o inglês com os nomes trocados)
  // (31 out 2026, P2) o &log virou a parte `log` do &config: a página dela, pedida em espanhol pelo nome antigo, sai em espanhol com o `aqui` e os eventos em espanhol
  const logEs = (await say("&ayuda log", esSid)).texto;
  assert.match(logEs, /^📖 Ayuda — &config › log\n/);
  assert.match(logEs, /`&config log canal [<‹]#canal\|aqui\|id[>›]` — define el canal/);
  assert.match(logEs, /`sanciones` · `miembros`/);
  assert.match(paginaEs.adeus, /`\{usuario\}` se convierte en el \*\*nombre\*\*/);
  assert.match(paginaEs.warn, /en el modo `acumular`/);
  // (31 out 2026, P2) o &purge mudou a ordem do uso (pessoa antes da quantidade, com a faixa): mesma exigência
  assert.match(paginaEs.limpar, /\*\*Uso:\*\* `&limpiar \[@usuario\] ‹1–100› \| todo`\n\*\*Permiso:\*\* ManageMessages/);
  assert.match(paginaEs.limpar, /\*\*Parámetros\*\*\n• `‹1–100›` — cuántos mensajes borrar \(los últimos\)\n• `\[@usuario\]` — solo los mensajes de esa persona/);
  // (31 out 2026, P2) a página do log (agora `&config › log`) traz os eventos na própria página, em
  // espanhol, em vez de um subtema à parte — e diz que as novidades vão sempre ao log
  assert.match(logEs, /\*\*Eventos:\*\* `sanciones` · `miembros` \(entradas\/salidas\) · `mensajes` \(borrados\/editados\) · `roles` · `comandos`/);
  assert.match(logEs, /Las \*\*novedades de Judy\*\* van siempre a este canal\./);
});
