  assert.equal(rajada.acharOdio("n.i.g.g.a"), "nigga");
  assert.equal(rajada.acharOdio("Falandooo con la pared", ["coon"]), null);
  assert.equal(rajada.acharOdio("maine cooon", ["coon"]), "coon");
