  const novos = [
    { feedId: 1, titulo: "CVE-2026-0001 critical bug" },
    { feedId: 2, titulo: "Lançamento do Judy 2.0" },
    { feedId: 3, titulo: "Apagão deixa Madrid sem energia" },
    { feedId: 4, titulo: "Receita de bolo" },
  ];
