  for (const f of fs.readdirSync("modulos/core")) assert.doesNotMatch(fs.readFileSync(`modulos/core/${f}`, "utf8"), /export async function cmd[A-Z]/, f);
  const g = fs.readFileSync("modulos/moderacao/geral.js", "utf8");
