  const nomes = REGISTRO.flatMap((x) => [x.id, ...(x.apelidos ?? []), x.es?.nome, ...Object.values(x.nomes ?? {})]).filter(Boolean);
  for (const n of ["chat", "ia", "personalidade", "personality", "personalidad"]) assert.ok(!nomes.includes(n), n);
