  assert.equal(segunda._tamanho(), segunda.MAX);
  segunda.lembrarPunicao({ tipo: "mensagem", categoria: "sentinela", serverId: SID, userId: CAIO, evidencia: { texto: GOLPE } }, { agora: AGORA - segunda.VALIDADE_MS - 1 });
