  rev._ligarParaTestes();
  const antes = rev._trocarEnvioParaTestes(async (_dm, emb) => { msgs.push(emb); return { id: U(800 + msgs.length), react: async (x) => { (msgs.at(-1).reacoes ??= []).push(decodeURIComponent(x)); } }; });
